    input  logic y,
    output logic z
);
    assign z = ~(x ^ y);
endmodule

module TopModule (
    input  logic x,
    input  logic y,
    output logic z
);

    logic a1_out, a2_out;
    logic b1_out, b2_out;
    logic or_out, and_out;

    // First pair of A and B submodules
    mod_a u_a1 (
        .x(x),
        .y(y),
        .z(a1_out)
    );

    mod_b u_b1 (
        .x(x),
        .y(y),
        .z(b1_out)
    );

    // Second pair of A and B submodules
    mod_a u_a2 (
        .x(x),
        .y(y),
        .z(a2_out)
    );

    mod_b u_b2 (
        .x(x),
        .y(y),
        .z(b2_out)
    );

    // OR gate for the first pair
    assign or_out = a1_out | b1_out;

    // AND gate for the second pair
    assign and_out = a2_out & b2_out;

    // XOR gate combining OR and AND outputs
    assign z = or_out ^ and_out;

